(args, got, expected) => {
    const vals = args[0];
    if (!Array.isArray(got)) return false;
    if (!got.length) return vals.length === 0;
    if (got[0] === null) return false;
    // rebuild the tree from level order
    const mk = v => ({ v, l: null, r: null });
    const root = mk(got[0]), q = [root];
    let i = 1, qi = 0;
    while (qi < q.length && i < got.length) {
      const n = q[qi++];
      if (i < got.length && got[i] !== null) { n.l = mk(got[i]); q.push(n.l); } i++;
      if (i < got.length && got[i] !== null) { n.r = mk(got[i]); q.push(n.r); } i++;
    }
    if (i < got.length) return false;
    // in-order must equal the list; heights must be balanced
    const order = [];
    let ok = true;
    const walk = n => {
      if (!n) return 0;
      const hl = walk(n.l);
      order.push(n.v);
      const hr = walk(n.r);
      if (Math.abs(hl - hr) > 1) ok = false;
      return 1 + Math.max(hl, hr);
    };
    walk(root);
    return ok && order.length === vals.length && order.every((x, k) => x === vals[k]);
  }

