function sortedChainToTree(head: ListNode | null): TreeNode | null {
  const vals: number[] = [];
  for (let n = head; n; n = n.next) vals.push(n.val);
  const build = (lo: number, hi: number): TreeNode | null => {
    if (lo > hi) return null;
    const mid = (lo + hi + 1) >> 1; // upper middle; lower middle works too
    return new TreeNode(vals[mid], build(lo, mid - 1), build(mid + 1, hi));
  };
  return build(0, vals.length - 1);
}

