function sortedChainToTree(head: ListNode | null): TreeNode | null {
  let n = 0;
  for (let p = head; p; p = p.next) n++;
  let cur = head;
  const build = (size: number): TreeNode | null => {
    if (size === 0) return null;
    const leftSize = size >> 1;
    const left = build(leftSize);
    const root = new TreeNode(cur!.val, left);
    cur = cur!.next;
    root.right = build(size - leftSize - 1);
    return root;
  };
  return build(n);
}

